import {totalReturn,justifiedBook,fiveYear,stress,forecast} from './model.js';
const config=JSON.parse(document.querySelector('#bank-inputs').textContent);
const money=x=>'C$'+x.toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct=x=>(x>=0?'+':'')+(x*100).toFixed(1)+'%';
const num=(form,name)=>{const el=form.elements.namedItem(name);if(el.value.trim()===''||!el.checkValidity())throw Error('Enter a valid '+el.labels[0].textContent.trim()+'.');return Number(el.value);};
const write=(root,fn)=>{try{fn();root.querySelector('[data-error]').textContent='';}catch(e){root.querySelector('[data-error]').textContent=e.message;}};
const f=document.querySelector('#valuation-form');
f.addEventListener('input',()=>write(f,()=>{const r=totalReturn(num(f,'price'),num(f,'eps'),num(f,'pe'),num(f,'cash'));f.querySelector('[data-value]').textContent=money(r.value);f.querySelector('[data-return]').textContent=pct(r.totalReturn);f.querySelector('[data-hurdle]').textContent=money((r.value+num(f,'cash'))/1.1);}));
for(const button of document.querySelectorAll('[data-preset]'))button.addEventListener('click',()=>{const c=config.caseValues.find(x=>x.name===button.dataset.preset);f.elements.price.value=config.market.price;f.elements.eps.value=c.eps.toFixed(4);f.elements.pe.value=c.pe;f.elements.cash.value=(config.dividend*4).toFixed(2);f.dispatchEvent(new Event('input'));});
f.addEventListener('reset',()=>setTimeout(()=>f.dispatchEvent(new Event('input'))));
const b=document.querySelector('#book-form');b.addEventListener('input',()=>write(b,()=>{const roe=num(b,'roe')/100,cost=num(b,'cost')/100,growth=num(b,'growth')/100,r=justifiedBook(roe,cost,growth),bv=num(b,'book');b.querySelector('[data-pb]').textContent=r.pb.toFixed(2)+'×';b.querySelector('[data-book-value]').textContent=money(r.pb*bv);b.querySelector('[data-implied-roe]').textContent=((growth+(config.market.price/bv)*(cost-growth))*100).toFixed(1)+'%';}));
const s=document.querySelector('#stress-form');s.addEventListener('input',()=>write(s,()=>{const r=stress(config,{revenueChange:num(s,'revenue')/100,expenseChange:num(s,'expense')/100,extraPclBps:num(s,'pcl')}),ret=totalReturn(config.market.price,Math.max(0,r.eps),config.basePE,config.dividend*4);s.querySelector('[data-stress-eps]').textContent=money(r.eps);s.querySelector('[data-stress-return]').textContent=pct(ret.totalReturn);s.querySelector('[data-credit-cost]').textContent=money(config.loanProxy*num(s,'pcl')/10000)+'m';}));
const h=document.querySelector('#five-form');h.addEventListener('input',()=>write(h,()=>{const r=fiveYear({price:num(h,'price'),eps:num(h,'eps'),growth:num(h,'growth')/100,exitPE:num(h,'pe'),dividend:num(h,'cash'),dividendGrowth:num(h,'cashGrowth')/100});h.querySelector('[data-irr]').textContent=pct(r.cashIRR);h.querySelector('[data-wealth]').textContent=money(r.final);h.querySelector('[data-five-rows]').innerHTML=r.rows.map(x=>`<tr><th scope="row">${x.year}</th><td>${money(x.eps)}</td><td>${money(x.dividend)}</td><td>${money(x.cumulative)}</td><td>${money(x.price)}</td></tr>`).join('');const values=[num(h,'price'),...r.rows.map(x=>x.price+x.cumulative)],max=Math.max(...values),points=values.map((v,i)=>`${50+i*100},${200-v/max*160}`).join(' ');h.querySelector('[data-five-line]').setAttribute('points',points);}));
for(const form of [f,b,s,h])form.dispatchEvent(new Event('input'));
document.querySelector('#download-scenario').addEventListener('click',()=>{try{const r=totalReturn(num(f,'price'),num(f,'eps'),num(f,'pe'),num(f,'cash'));const csv='bank,as_of,price,analyst_eps,exit_pe,cash_dividends,model_value,total_return\n'+[config.ticker,config.market.date,num(f,'price'),num(f,'eps'),num(f,'pe'),num(f,'cash'),r.value,r.totalReturn].join(',')+'\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=config.id+'-custom-scenario.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),0);}catch(e){f.querySelector('[data-error]').textContent=e.message;}});
for(const form of [f,b,s,h])form.addEventListener('submit',event=>event.preventDefault());
